-- Los 18 productos de la hoja "pendientes" aún no existen en Defontana: quedan con codigo_defontana NULL.

ALTER TABLE productos ADD COLUMN IF NOT EXISTS codigo_defontana text;

CREATE UNIQUE INDEX IF NOT EXISTS productos_codigo_defontana_key
  ON productos (codigo_defontana) WHERE codigo_defontana IS NOT NULL;

